def donor_blocks(trigger):
    with _DONOR_LOCK:
        tier = _DONOR_TIER
    return tier == 'donor' or (tier == 'supporter' and trigger in ('start', 'stop', 'save'))


def set_donor_tier(tier):
    global _DONOR_TIER
    if tier not in ('none', 'supporter', 'donor'):
        raise ValueError('Invalid donor tier')
    with _DONOR_LOCK:
        _DONOR_TIER = tier
    scheduler = globals().get('_VISIT_SCHEDULER')
    if scheduler is not None:
        with scheduler.lock:
            scheduler.jobs = [(name, delay) for name, delay in scheduler.jobs
                              if not donor_blocks(name)]
            scheduler.pending = {name for name, _delay in scheduler.jobs}
            if scheduler.active:
                scheduler.pending.add(scheduler.active)
                if donor_blocks(scheduler.active):
                    _VISIT_ABORT.set()


def donor_data_dir():
    if sys.platform.startswith('win'):
        base = os.environ.get('LOCALAPPDATA') or os.path.join(os.path.expanduser('~'), 'AppData', 'Local')
    else:
        base = os.environ.get('XDG_DATA_HOME') or os.path.join(os.path.expanduser('~'), '.local', 'share')
    path = os.path.join(base, 'TrackerPulse')
    os.makedirs(path, mode=0o700, exist_ok=True)
    return path


def atomic_private_write(path, data):
    folder = os.path.dirname(path)
    fd, temporary = tempfile.mkstemp(prefix='.tp-', dir=folder)
    try:
        with os.fdopen(fd, 'wb') as stream:
            stream.write(data)
            stream.flush()
            os.fsync(stream.fileno())
        os.replace(temporary, path)
        try:
            os.chmod(path, 0o600)
        except OSError:
            pass
    finally:
        try:
            os.remove(temporary)
        except FileNotFoundError:
            pass


def local_secret():
    path = os.path.join(donor_data_dir(), 'receipt.key')
    try:
        with open(path, 'rb') as stream:
            key = stream.read(64)
        if len(key) != 32:
            raise ValueError('Invalid local receipt key; restore your original key file.')
        return key
    except FileNotFoundError:
        key = secrets.token_bytes(32)
        try:
            fd = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
        except FileExistsError:
            return local_secret()
        with os.fdopen(fd, 'wb') as stream:
            stream.write(key)
        return key


def machine_fingerprint():
    import hashlib
    import hmac
    identifier = None
    if sys.platform.startswith('win'):
        try:
            import winreg
            with winreg.OpenKey(winreg.HKEY_LOCAL_MACHINE,
                                r'SOFTWARE\Microsoft\Cryptography', 0,
                                winreg.KEY_READ | getattr(winreg, 'KEY_WOW64_64KEY', 0)) as key:
                identifier = winreg.QueryValueEx(key, 'MachineGuid')[0]
        except Exception:
            pass
    else:
        for path in ('/etc/machine-id', '/var/lib/dbus/machine-id'):
            try:
                with open(path, 'r', encoding='ascii') as stream:
                    identifier = stream.read(256).strip()
                if identifier:
                    break
            except OSError:
                pass
    if not identifier:
        # Weaker fallback: bind to a per-install secret, without inventing a hardware ID.
        identifier = 'install:' + local_secret().hex()
    return hmac.new(b'TrackerPulse/device/v1', identifier.encode('utf-8'), hashlib.sha256).hexdigest()


def receipt_cipher():
    import hashlib
    from cryptography.hazmat.primitives.ciphers.aead import AESGCM
    key = hashlib.sha256(b'TrackerPulse/local-receipt/v1' + local_secret()
                         + machine_fingerprint().encode('ascii')).digest()
    return AESGCM(key)


def load_donor_receipt():
    path = os.path.join(donor_data_dir(), 'donor.license')
    if not os.path.isfile(path):
        return None, ''
    try:
        with open(path, 'rb') as stream:
            data = stream.read(1024 * 1024)
        if data[:5] != b'TPD1\n':
            raise ValueError('Unrecognized donor receipt')
        plain = receipt_cipher().decrypt(data[5:17], data[17:], b'TrackerPulse/receipt/v1')
        receipt = json.loads(plain.decode('utf-8'))
        if receipt.get('machine') != machine_fingerprint() or receipt.get('version') != 1:
            raise ValueError('Receipt belongs to a different system')
        usd = Decimal(receipt['usd_value'])
        if not usd.is_finite() or usd <= 0:
            raise ValueError('Invalid receipt amount')
        expected = 'donor' if usd >= DONOR_THRESHOLD_USD else 'supporter'
        if receipt.get('tier') != expected:
            raise ValueError('Invalid receipt tier')
        if receipt.get('asset') not in ('BTC', 'ETH', 'USDC', 'USDT'):
            raise ValueError('Invalid receipt asset')
        wanted = BTC_DONATION_ADDRESS if receipt['asset'] == 'BTC' else EVM_DONATION_ADDRESS
        if receipt.get('recipient') != wanted:
            raise ValueError('Receipt has another recipient')
        expected_network = 'bitcoin-mainnet' if receipt['asset'] == 'BTC' else 'ethereum-mainnet'
        if receipt.get('network') != expected_network:
            raise ValueError('Invalid receipt network')
        # Do not reapply the claim window: a valid activated receipt remains usable offline.
        return receipt, ''
    except ImportError:
        return None, 'Install cryptography to read the donor receipt.'
    except Exception:
        return None, 'Donor receipt could not be verified for this system. Restore the original receipt/key or reverify a recent payment.'


def save_donor_receipt(payment, previous=None):
    if previous and previous.get('network') == payment['network'] and previous.get('txid') == payment['txid']:
        return previous
    if previous and previous.get('tier') == 'donor':
        return previous                  # Never downgrade a full donor.
    receipt = dict(payment)
    receipt.update(version=1, machine=machine_fingerprint(), activated_at=int(time.time()))
    receipt['tier'] = 'donor' if Decimal(payment['usd_value']) >= DONOR_THRESHOLD_USD else 'supporter'
    nonce = secrets.token_bytes(12)
    plain = json.dumps(receipt, sort_keys=True, separators=(',', ':')).encode('utf-8')
    encoded = b'TPD1\n' + nonce + receipt_cipher().encrypt(nonce, plain, b'TrackerPulse/receipt/v1')
    atomic_private_write(os.path.join(donor_data_dir(), 'donor.license'), encoded)
    return receipt


def payment_request(url, payload=None):
    """Read-only JSON HTTP request, TLS verified; never submits any transaction."""
    data = None if payload is None else json.dumps(payload).encode('utf-8')
    request = urllib.request.Request(url, data=data, headers={
        'User-Agent': 'TrackerPulse/4.0', 'Accept': 'application/json',
        'Content-Type': 'application/json'})
    with urllib.request.urlopen(request, timeout=9) as response:
        body = response.read(2_000_001)
        if len(body) > 2_000_000:
            raise PaymentServiceError('Payment API returned too much data')
        # JSON integers remain integers; prices are parsed separately with Decimal.
        return json.loads(body.decode('utf-8'), parse_float=Decimal)


def claim_age(block_timestamp, now=None):
    current = time.time() if now is None else now
    age = current - int(block_timestamp)
    if age < -300:
        raise PaymentServiceError('Block timestamp is in the future. Check your system clock.')
    if age > CLAIM_WINDOW_SECONDS:
        raise PaymentRejected('This payment is older than 24 hours and cannot be claimed initially.')


def verify_bitcoin(txid, now=None):
    txid = txid.strip().lower()
    if not re.fullmatch(r'[0-9a-f]{64}', txid):
        raise PaymentRejected('Enter a 64-character Bitcoin transaction ID.')
    errors = []
    for base in BTC_APIS:
        try:
            tx = payment_request(base + '/tx/' + txid)
            if tx.get('txid', '').lower() != txid:
                raise PaymentServiceError('Bitcoin API transaction mismatch')
            paid = sum(int(output.get('value', 0)) for output in tx.get('vout', [])
                       if output.get('scriptpubkey_address') == BTC_DONATION_ADDRESS)
            if paid <= 0:
                raise PaymentRejected('This Bitcoin transaction did not pay the displayed donation address.')
            status = tx.get('status') or {}
            if not status.get('confirmed'):
                raise PaymentPending('Bitcoin payment is unconfirmed. Checking again in 30 seconds.')
            claim_age(status['block_time'], now)
            height = int(payment_request(base + '/blocks/tip/height'))
            confirms = height - int(status['block_height']) + 1
            if confirms < BTC_REQUIRED_CONFIRMATIONS:
                raise PaymentPending(f'Bitcoin confirmations: {confirms}/{BTC_REQUIRED_CONFIRMATIONS}. Checking again in 30 seconds.')
            # Confirm that the reported block is still in the best chain.
            blockstatus = payment_request(base + '/block/' + status['block_hash'] + '/status')
            if not blockstatus.get('in_best_chain'):
                raise PaymentPending('Bitcoin block is not in the best chain. Try again later.')
            return {'asset': 'BTC', 'network': 'bitcoin-mainnet', 'txid': txid,
                    'recipient': BTC_DONATION_ADDRESS, 'amount': str(Decimal(paid) / Decimal(10**8)),
                    'block_timestamp': int(status['block_time']), 'confirmations': confirms}
        except (PaymentRejected, PaymentPending):
            raise
        except Exception as exc:
            errors.append(type(exc).__name__)
    raise PaymentServiceError('Bitcoin public services are unavailable or the transaction was not found. Retry later.')


def rpc_request(endpoint, method, params):
    response = payment_request(endpoint, {'jsonrpc': '2.0', 'id': 1, 'method': method, 'params': params})
    if not isinstance(response, dict) or response.get('error') or 'result' not in response:
        raise PaymentServiceError('Ethereum RPC rejected ' + method)
    return response['result']


def token_amount(receipt, asset):
    contract = TOKEN_CONTRACTS[asset]
    amount = 0
    for log in receipt.get('logs', []):
        if not isinstance(log, dict):
            continue
        topics = log.get('topics') or []
        if (log.get('removed') or log.get('address', '').lower() != contract
                or len(topics) != 3 or topics[0].lower() != TRANSFER_TOPIC):
            continue
        if not re.fullmatch(r'0x[0-9a-fA-F]{64}', topics[2]):
            continue
        recipient = '0x' + topics[2][-40:].lower()
        if recipient != EVM_DONATION_ADDRESS:
            continue
        data = log.get('data', '')
        if re.fullmatch(r'0x[0-9a-fA-F]{64}', data):
            amount += int(data, 16)
    return Decimal(amount) / Decimal(10**6)


def verify_ethereum(asset, txid, now=None):
    txid = txid.strip().lower()
    if not txid.startswith('0x'):
        txid = '0x' + txid
    if not re.fullmatch(r'0x[0-9a-f]{64}', txid):
        raise PaymentRejected('Enter an Ethereum mainnet transaction hash (0x plus 64 hex characters).')
    if asset not in ('ETH', 'USDC', 'USDT'):
        raise PaymentRejected('Unsupported Ethereum asset')
    for endpoint in ETH_RPC_APIS:
        try:
            call = lambda method, params: rpc_request(endpoint, method, params)
            if int(call('eth_chainId', []), 16) != 1:
                raise PaymentServiceError('RPC is not Ethereum mainnet')
            tx = call('eth_getTransactionByHash', [txid])
            if tx is None:
                raise PaymentServiceError('Transaction not found at this endpoint')
            if tx.get('hash', '').lower() != txid:
                raise PaymentServiceError('Transaction hash mismatch')
            receipt = call('eth_getTransactionReceipt', [txid])
            if receipt is None:
                raise PaymentPending('Ethereum transaction is pending. Checking again in 30 seconds.')
            if receipt.get('transactionHash', '').lower() != txid:
                raise PaymentServiceError('Receipt hash mismatch')
            if int(receipt.get('status', '0x0'), 16) != 1:
                raise PaymentRejected('This Ethereum transaction failed/reverted. It cannot activate donor status.')
            block = call('eth_getBlockByNumber', [receipt['blockNumber'], False])
            if not block or block.get('hash', '').lower() != receipt.get('blockHash', '').lower():
                raise PaymentPending('Transaction block changed. Retry after finality.')
            claim_age(int(block['timestamp'], 16), now)
            if asset == 'ETH':
                if (tx.get('to') or '').lower() != EVM_DONATION_ADDRESS:
                    raise PaymentRejected('ETH payment must be a direct transfer to the displayed address. Internal/batched ETH transfers are not supported.')
                amount = Decimal(int(tx.get('value', '0x0'), 16)) / Decimal(10**18)
            else:
                amount = token_amount(receipt, asset)
            if amount <= 0:
                raise PaymentRejected('No transfer of the selected asset to the displayed address was found. Check coin, network and transaction ID.')
            final = call('eth_getBlockByNumber', ['finalized', False])
            if not final or int(final['number'], 16) < int(receipt['blockNumber'], 16):
                raise PaymentPending('Ethereum transaction is mined but not finalized yet. Checking again in 30 seconds.')
            return {'asset': asset, 'network': 'ethereum-mainnet', 'txid': txid,
                    'recipient': EVM_DONATION_ADDRESS, 'amount': str(amount),
                    'block_timestamp': int(block['timestamp'], 16), 'finalized': True}
        except (PaymentRejected, PaymentPending):
            raise
        except Exception:
            continue
    raise PaymentServiceError('Ethereum public services are unavailable, or this hash is not on Ethereum mainnet. Retry later.')


def price_usd(asset):
    """Spot conversion at initial verification; frozen in the activated receipt."""
    try:
        data = payment_request(f'https://api.coinbase.com/v2/prices/{asset}-USD/spot')
        price = Decimal(str(data['data']['amount']))
        if not price.is_finite() or price <= 0:
            raise ValueError()
        return price, 'Coinbase spot'
    except Exception:
        ids = {'BTC': 'bitcoin', 'ETH': 'ethereum', 'USDC': 'usd-coin', 'USDT': 'tether'}
        try:
            data = payment_request('https://api.coingecko.com/api/v3/simple/price?ids='
                                   + ids[asset] + '&vs_currencies=usd')
            price = Decimal(str(data[ids[asset]]['usd']))
            if not price.is_finite() or price <= 0:
                raise ValueError()
            return price, 'CoinGecko spot'
        except Exception:
            raise PaymentServiceError('USD price services are unavailable; no status has been granted. Retry later.')


def verify_donation(asset, txid, now=None):
    try:
        from cryptography.hazmat.primitives.ciphers.aead import AESGCM
    except ImportError:
        raise PaymentServiceError('Install the receipt dependency first: python -m pip install cryptography')
    payment = verify_bitcoin(txid, now) if asset == 'BTC' else verify_ethereum(asset, txid, now)
    price, source = price_usd(asset)
    value = Decimal(payment['amount']) * price
    if value <= 0 or not value.is_finite():
        raise PaymentRejected('Payment has no positive USD value')
    payment.update(usd_value=str(value), usd_price=str(price), price_source=source,
                   valued_at=int(time.time()))
    return payment


