def _browser_family(executable):
    name = os.path.basename(executable).lower()
    if 'firefox' in name:
        return 'firefox'
    if any(x in name for x in ('chrome', 'chromium', 'msedge', 'brave', 'vivaldi')):
        return 'chromium'
    return None


def find_default_browser():
    """Return (supported executable, family), or None. Never guesses Chrome."""
    override = os.environ.get('TRACKERPULSE_BROWSER', '').strip().strip('"')
    if override:
        path = shutil.which(override) or override
        family = _browser_family(path)
        return (path, family) if os.path.isfile(path) and family else None

    if sys.platform.startswith('win'):
        try:
            import winreg
            choice = r'Software\Microsoft\Windows\Shell\Associations\UrlAssociations\https\UserChoice'
            with winreg.OpenKey(winreg.HKEY_CURRENT_USER, choice) as key:
                progid = winreg.QueryValueEx(key, 'ProgId')[0]
            with winreg.OpenKey(winreg.HKEY_CLASSES_ROOT, progid + r'\shell\open\command') as key:
                command = os.path.expandvars(winreg.QueryValueEx(key, None)[0]).strip()
            # Do not execute the registry's whole command, URL substitutions or shell wrappers.
            if command.startswith('"'):
                executable = command.split('"', 2)[1]
            else:
                match = re.match(r'(.+?\.exe)(?:\s|$)', command, re.I)
                executable = match.group(1) if match else ''
            family = _browser_family(executable)
            if os.path.isfile(executable) and family:
                return executable, family
        except Exception:
            pass
        return None

    try:
        desktop = subprocess.check_output(
            ['xdg-settings', 'get', 'default-web-browser'],
            text=True, timeout=3, stderr=subprocess.DEVNULL).strip()
        if not desktop or os.path.basename(desktop) != desktop:
            return None
        roots = [os.path.expanduser('~/.local/share')]
        roots += os.environ.get('XDG_DATA_DIRS', '/usr/local/share:/usr/share').split(':')
        for root in roots:
            path = os.path.join(root, 'applications', desktop)
            if not os.path.isfile(path):
                continue
            ini = configparser.ConfigParser(interpolation=None)
            ini.read(path, encoding='utf-8')
            parts = shlex.split(ini.get('Desktop Entry', 'Exec'))
            if not parts:
                continue
            # env/flatpak/snap wrappers are not safe to treat as browser PIDs.
            executable = shutil.which(parts[0]) or parts[0]
            if os.path.basename(executable) in ('env', 'flatpak', 'snap'):
                return None
            if os.path.islink(executable):
                resolved = os.path.realpath(executable)
                if '/snap/' in resolved or resolved.endswith('/snap'):
                    return None
            family = _browser_family(executable)
            if os.path.isfile(executable) and family:
                return executable, family
    except Exception:
        pass
    return None


def browser_command(executable, family, profile, url):
    if family == 'firefox':
        return [executable, '--no-remote', '--new-instance', '--profile', profile,
                '--new-window', url]
    if family == 'chromium':
        return [executable, '--user-data-dir=' + profile, '--no-first-run',
                '--no-default-browser-check', '--new-window', url]
    raise ValueError('Unsupported browser family')


def close_owned_browser(process, report=print):
    """Terminate only the fresh isolated browser launch, never by image name."""
    if process.poll() is not None:
        return
    try:
        if sys.platform.startswith('win'):
            # /PID, not /IM: no global chrome.exe/firefox.exe kill.
            subprocess.run(['taskkill', '/PID', str(process.pid), '/T', '/F'],
                           stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                           timeout=8, creationflags=getattr(subprocess, 'CREATE_NO_WINDOW', 0))
        else:
            # Popen(start_new_session=True) creates this app-owned process group.
            os.killpg(process.pid, signal.SIGTERM)
            try:
                process.wait(timeout=3)
            except subprocess.TimeoutExpired:
                os.killpg(process.pid, signal.SIGKILL)
        process.wait(timeout=5)
    except (ProcessLookupError, ChildProcessError):
        pass
    except Exception as exc:
        report('Isolated browser cleanup: ' + str(exc)[:120])


