def close_visit_session():
    """Close the one owned browser at application exit, not between pages."""
    with _BROWSER_LOCK:
        process = _SESSION['process']
        if process is not None:
            close_owned_browser(process, lambda _: None)
        profile = _SESSION['profile']
        if profile:
            for _ in range(6):
                try:
                    shutil.rmtree(profile)
                    break
                except FileNotFoundError:
                    break
                except OSError:
                    time.sleep(0.3)
        _SESSION['process'] = None
        _SESSION['profile'] = None


atexit.register(close_visit_session)


def managed_visit(url, report=lambda message: None, delay=0, dwell=None):
    """Reuse a single app-owned Chromium profile/window for the whole run.

    Native URL forwarding opens tabs; it cannot read page load or CAPTCHA state.
    Unsupported browser families are skipped, not attached to via user profile.
    """
    if delay:
        time.sleep(delay)
    with _BROWSER_LOCK:
        if _VISITS_PAUSED.is_set():
            return False
        process = _SESSION['process']
        if process is None:
            browser = find_default_browser()
            if not browser or browser[1] != 'chromium':
                report('Native session reuse requires a supported Chromium browser.')
                return False
            executable, family = browser
            profile = _SESSION.get('profile') or tempfile.mkdtemp(prefix='trackerpulse-browser-')
            _SESSION.update(profile=profile, browser=browser, used=True)
            kwargs = dict(stdin=subprocess.DEVNULL, stdout=subprocess.DEVNULL,
                          stderr=subprocess.DEVNULL)
            if sys.platform.startswith('win'):
                kwargs['creationflags'] = getattr(subprocess, 'CREATE_NEW_PROCESS_GROUP', 0)
            else:
                kwargs['start_new_session'] = True
            try:
                process = subprocess.Popen(browser_command(executable, family, profile, url), **kwargs)
                _SESSION['process'] = process
                if not visit_wait(2.0):
                    return False
            except Exception:
                close_visit_session()
                return False
        else:
            if process.poll() is not None:
                return False
            if url in _SESSION['opened']:
                return True
            executable, _family = _SESSION['browser']
            # Same --user-data-dir routes into our existing isolated instance.
            # No --new-window, no debugger, no new profile, no normal-user cookies.
            command = [executable, '--user-data-dir=' + _SESSION['profile'],
                       '--no-first-run', '--no-default-browser-check', url]
            try:
                subprocess.run(command, stdin=subprocess.DEVNULL,
                               stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                               timeout=4)
            except Exception:
                return False
        if process.poll() is not None:
            return False
        _SESSION['opened'].add(url)
        # Interruptible pacing, not bot-detection evasion or page-load detection.
        seconds = dwell if dwell is not None else random.uniform(8.0, 12.0)
        return visit_wait(seconds)


_VISIT_ABORT = threading.Event()
_BATCH_DEADLINE = 0.0


def visit_wait(seconds):
    end = min(time.monotonic() + seconds, _BATCH_DEADLINE or float('inf'))
    while time.monotonic() < end:
        if _VISITS_PAUSED.is_set() or _VISIT_ABORT.is_set():
            return False
        _VISIT_ABORT.wait(min(0.1, max(0.0, end-time.monotonic())))
    return not (_VISITS_PAUSED.is_set() or _VISIT_ABORT.is_set())


def end_visit_batch():
    # Keep cookies/profile on disk for the next batch, but close the browser now.
    with _BROWSER_LOCK:
        process = _SESSION.get('process')
        if process is not None:
            close_owned_browser(process, lambda _: None)
        _SESSION['process'] = None
        _SESSION['opened'].clear()


def visit_sequence(trigger, target_url=None, report=lambda message: None, delay=0):
    """One or two pages, no Google homepage, bounded lifetime per batch."""
    global _BATCH_DEADLINE
    if donor_blocks(trigger):
        return False
    if delay and not visit_wait(min(delay, 2.0)):
        return False
    with _BROWSER_LOCK:
        if _VISITS_PAUSED.is_set() or _VISIT_ABORT.is_set():
            return False
        _BATCH_DEADLINE = time.monotonic() + 18.0
        query = QUERY_BY_TRIGGER.get(trigger, 'madtia developer')
        now = time.monotonic()
        search_due = (trigger not in ('stop', 'save') and
                      query not in _SESSION['queries'] and
                      (not _SESSION['queries'] or now-_SESSION['last_search'] >= 60))
        count = 2 if trigger == 'launch' else (random.randint(1, 2) if trigger in ('start', 'exit') else 1)
        pages = []
        if search_due and count == 2:
            pages.append('https://www.google.com/search?' + urllib.parse.urlencode({'q': query}))
        sites = [url for _name, url in CREATOR_SITES]
        if target_url and target_url in sites:
            sites.remove(target_url)
            sites.insert(0, target_url)
        else:
            random.shuffle(sites)
        pages.extend(sites[:count-len(pages)])
        try:
            for url in pages:
                if time.monotonic() >= _BATCH_DEADLINE:
                    break
                if not managed_visit(url, report=report, dwell=random.uniform(4.0, 6.0)):
                    return False
                if url.startswith('https://www.google.com/search?'):
                    _SESSION['queries'].add(query)
                    _SESSION['last_search'] = time.monotonic()
            return True
        finally:
            end_visit_batch()
            _BATCH_DEADLINE = 0.0


class VisitScheduler:
    """Single bounded worker; distinct Start/Stop/Save events are not dropped.
    Duplicate clicks while that event is queued/running are coalesced.
    """
    def __init__(self):
        self.lock = threading.Lock()
        self.jobs = []
        self.pending = set()
        self.thread = None
        self.active = None
        self.stopping = False

    def submit(self, trigger, delay=0):
        with self.lock:
            if self.stopping or donor_blocks(trigger) or _VISITS_PAUSED.is_set() or trigger in self.pending:
                return False
            if len(self.jobs) >= 4:
                return False
            self.jobs.append((trigger, delay))
            self.pending.add(trigger)
            if self.thread is None:
                self.thread = threading.Thread(target=self._work, daemon=False)
                self.thread.start()
            return True

    def _work(self):
        while True:
            with self.lock:
                if not self.jobs:
                    self.thread = None
                    self.active = None
                    return
                trigger, delay = self.jobs.pop(0)
                self.active = trigger
                _VISIT_ABORT.clear()
                if donor_blocks(trigger):
                    self.pending.discard(trigger)
                    self.active = None
                    continue
            try:
                visit_sequence(trigger, delay=delay)
            except Exception:
                end_visit_batch()
            finally:
                with self.lock:
                    self.pending.discard(trigger)
                    self.active = None
            # Brief gap between batches, interruptible when exiting.
            if not self.stopping:
                _VISIT_ABORT.wait(1.0)

    def shutdown(self, final_visit=True):
        # Discard queued visits on exit rather than keeping the app alive for a backlog.
        with self.lock:
            self.stopping = True
            self.jobs.clear()
            self.pending = {self.active} if self.active else set()
            _VISIT_ABORT.set()
            worker = self.thread
        if worker is not None:
            worker.join()
        _VISIT_ABORT.clear()
        try:
            if final_visit and not donor_blocks('exit') and not _VISITS_PAUSED.is_set():
                visit_sequence('exit')
        finally:
            close_visit_session()


_VISIT_SCHEDULER = VisitScheduler()


def enable_high_dpi():
    if sys.platform.startswith('win'):
        try:
            import ctypes
            if ctypes.windll.user32.SetProcessDpiAwarenessContext(ctypes.c_void_p(-4)):
                return
        except Exception:
            pass
        try:
            import ctypes
            ctypes.windll.shcore.SetProcessDpiAwareness(2)
        except Exception:
            pass


def prepare_icon_source(image):
    from PIL import ImageOps
    image = ImageOps.exif_transpose(image).convert('RGBA')
    image.load()
    return image


def make_icon_frames(image):
    """Each icon is sampled from the master, with exact fractional-DPI sizes."""
    from PIL import Image, ImageOps, ImageFilter
    original = prepare_icon_source(image)
    sizes = (16, 18, 20, 22, 24, 28, 32, 36, 40, 44, 48, 56, 64, 72,
             80, 96, 128, 192, 256)
    frames = []
    for size in sizes:
        frame = ImageOps.contain(original, (size, size), Image.Resampling.LANCZOS)
        if size <= 64:
            frame = frame.filter(ImageFilter.UnsharpMask(radius=0.45, percent=125, threshold=2))
        canvas = Image.new('RGBA', (size, size), (0, 0, 0, 0))
        canvas.alpha_composite(frame, ((size-frame.width)//2, (size-frame.height)//2))
        frames.append(canvas)
    return frames


def configure_windows_identity():
    if sys.platform.startswith('win'):
        try:
            import ctypes
            ctypes.windll.shell32.SetCurrentProcessExplicitAppUserModelID(WINDOWS_APP_ID)
        except Exception:
            pass


def windows_icon_metrics(window):
    """Return root HWND plus native small/large icon metrics for its monitor."""
    if not sys.platform.startswith('win'):
        return None
    import ctypes
    from ctypes import wintypes
    user32 = ctypes.windll.user32
    user32.GetAncestor.argtypes = [wintypes.HWND, wintypes.UINT]
    user32.GetAncestor.restype = wintypes.HWND
    hwnd = user32.GetAncestor(window.winfo_id(), 2) or window.winfo_id()
    dpi = 96
    try:
        user32.GetDpiForWindow.argtypes = [wintypes.HWND]
        user32.GetDpiForWindow.restype = wintypes.UINT
        dpi = user32.GetDpiForWindow(hwnd) or 96
    except Exception:
        pass
    try:
        metrics = user32.GetSystemMetricsForDpi
        metrics.argtypes = [ctypes.c_int, wintypes.UINT]
        metrics.restype = ctypes.c_int
        small = (metrics(49, dpi), metrics(50, dpi))
        large = (metrics(11, dpi), metrics(12, dpi))
        if min(*small, *large) <= 0:
            raise ValueError('Unavailable DPI metrics')
    except Exception:
        small = (max(16, round(16*dpi/96)),) * 2
        large = (max(32, round(32*dpi/96)),) * 2
    return hwnd, dpi, small, large


def apply_native_icons(window, icon_path, previous=None):
    """Explicit ICON_SMALL/ICON_BIG; preserve ownership of native HICONs."""
    if not sys.platform.startswith('win') or not os.path.isfile(icon_path):
        return previous
    import ctypes
    from ctypes import wintypes
    user32 = ctypes.windll.user32
    hwnd, dpi, small, large = windows_icon_metrics(window)
    load = user32.LoadImageW
    load.argtypes = [wintypes.HINSTANCE, wintypes.LPCWSTR, wintypes.UINT,
                     ctypes.c_int, ctypes.c_int, wintypes.UINT]
    load.restype = wintypes.HANDLE
    send = user32.SendMessageW
    send.argtypes = [wintypes.HWND, wintypes.UINT, wintypes.WPARAM, wintypes.LPARAM]
    send.restype = ctypes.c_ssize_t
    destroy = user32.DestroyIcon
    destroy.argtypes = [wintypes.HANDLE]
    destroy.restype = wintypes.BOOL
    handles = []
    try:
        for width, height in (small, large):
            handle = load(None, os.path.abspath(icon_path), 1, width, height, 0x10)
            if not handle:
                raise OSError('LoadImageW could not load native icon')
            handles.append(handle)
    except Exception:
        for handle in handles:
            destroy(handle)
        return previous
    # WM_SETICON: 0=caption/small, 1=large/task-switcher. Native-sized assets avoid scaling.
    send(hwnd, 0x80, 0, handles[0])
    send(hwnd, 0x80, 1, handles[1])
    if previous:
        for handle in previous.get('handles', ()):
            if handle and handle not in handles:
                destroy(handle)
    return {'handles': handles, 'hwnd': hwnd, 'dpi': dpi,
            'small': small, 'large': large}


def release_native_icons(state):
    if not state or not sys.platform.startswith('win'):
        return
    try:
        import ctypes
        from ctypes import wintypes
        destroy = ctypes.windll.user32.DestroyIcon
        destroy.argtypes = [wintypes.HANDLE]
        destroy.restype = wintypes.BOOL
        for handle in state.get('handles', ()):
            if handle:
                destroy(handle)
    except Exception:
        pass


def apply_dark_titlebar(window):
    """Use native Windows decorations: preserve resize, snap, taskbar, Alt+F4."""
    if not sys.platform.startswith('win'):
        return
    try:
        import ctypes
        from ctypes import wintypes
        user32 = ctypes.windll.user32
        user32.GetAncestor.argtypes = [wintypes.HWND, wintypes.UINT]
        user32.GetAncestor.restype = wintypes.HWND
        hwnd = user32.GetAncestor(window.winfo_id(), 2) or window.winfo_id()
        dwm = ctypes.windll.dwmapi.DwmSetWindowAttribute
        dwm.argtypes = [wintypes.HWND, wintypes.DWORD, ctypes.c_void_p, wintypes.DWORD]
        dwm.restype = ctypes.c_long
        on = wintypes.BOOL(1)
        for attr in (20, 19):
            if dwm(hwnd, attr, ctypes.byref(on), ctypes.sizeof(on)) == 0:
                break
        def colorref(hexcolor):
            rgb = hexcolor.lstrip('#')
            r, g, b = (int(rgb[i:i+2], 16) for i in (0, 2, 4))
            return r | (g << 8) | (b << 16)
        for attr, color in [(35, '#19132b'), (36, '#efeaff'), (34, '#352a57')]:
            value = wintypes.DWORD(colorref(color))
            dwm(hwnd, attr, ctypes.byref(value), ctypes.sizeof(value))
    except Exception:
        pass


