PARKED_INDICATORS = [
    'domain for sale', 'domain is for sale', 'buy this domain',
    'domain expired', 'domain has expired', 'this domain is expired',
    'register this domain', 'domain available', 'parked domain',
    'domain parking', 'coming soon', 'under construction',
    'page not found', '404 not found', 'namecheap',
    'godaddy parked', 'sedo domain parking', 'domain portfolio',
    'premium domain', 'afternic', 'escrow.com', 'dan.com/buy-domain',
    'undeveloped', 'this webpage was generated by the domain owner',
    'hugedomains.com', 'bodis.com', 'sedoparking',
]


def parse_tracker_line(line):
    """Extract a clean tracker URL (supports markdown links)."""
    line = line.strip()
    if line.startswith('[') and '](' in line and line.endswith(')'):
        line = line.split('](')[1].rstrip(')')
    return line


def read_trackers(path):
    seen, out = set(), []
    with open(path, 'r', encoding='utf-8', errors='ignore') as fh:
        for line in fh:
            url = parse_tracker_line(line)
            if url and not url.startswith('#') and url not in seen:
                seen.add(url)
                out.append(url)
    return out


def bdecode_simple(data):
    try:
        if not data:
            return None
        if data[0:1] == b'd':
            return (b'interval' in data or b'peers' in data
                    or b'failure reason' in data)
        return False
    except Exception:
        return False


def is_parked_or_expired_domain(content, url=None):
    if not content:
        return False
    try:
        low = content.decode('utf-8', errors='ignore').lower()
    except Exception:
        low = str(content).lower()
    if any(ind in low for ind in PARKED_INDICATORS):
        return True
    head = content[:500].lower()
    return b'<html' in head or b'<!doctype html' in head


def check_http_tracker(url, timeout=10):
    try:
        params = {
            'info_hash': b'\x00' * 20,
            'peer_id': b'-PY0001-' + bytes(random.randint(0, 255) for _ in range(12)),
            'port': 6881, 'uploaded': 0, 'downloaded': 0, 'left': 0,
            'compact': 1, 'event': 'started',
        }
        test_url = url + ("&" if "?" in url else "?") + urllib.parse.urlencode(params, doseq=True)
        req = urllib.request.Request(
            test_url, headers={'User-Agent': 'Python-Tracker-Checker/1.0'})

        with urllib.request.urlopen(req, timeout=timeout) as resp:
            status_code = resp.getcode()
            content = resp.read(200000)

            if is_parked_or_expired_domain(content, url):
                return 'invalid', 'parked/expired domain or advertising page'

            if bdecode_simple(content):
                if b'failure reason' in content:
                    return 'alive', 'valid tracker (returned failure reason)'
                if b'interval' in content or b'peers' in content:
                    return 'alive', 'valid tracker response'
                return 'alive', 'valid bencoded response'

            if status_code == 200:
                if b'<html' in content[:100].lower():
                    return 'invalid', 'returns HTML page (not a tracker)'
                if len(content) > 50000:
                    return 'invalid', 'response too large (likely not a tracker)'
                if b'<body' in content.lower() or b'<head' in content.lower():
                    return 'invalid', 'returns web page (not a tracker)'
                return 'dead', f'HTTP {status_code} but invalid tracker response'
            if 200 <= status_code < 400:
                return 'dead', f'HTTP {status_code} (no valid tracker data)'
            return 'dead', f'HTTP {status_code}'

    except urllib.error.HTTPError as e:
        if e.code in (400, 403):
            try:
                if bdecode_simple(e.read()):
                    return 'alive', f'HTTP {e.code} (valid tracker, invalid request)'
            except Exception:
                pass
        return 'dead', f'HTTP error {e.code}'
    except urllib.error.URLError as e:
        return 'dead', f'connection failed: {str(e.reason)[:50]}'
    except socket.timeout:
        return 'dead', 'timeout'
    except Exception as e:
        return 'dead', f'error: {str(e)[:50]}'


def check_udp_tracker(url, timeout=10):
    sock = None
    try:
        parsed = urlparse(url)
        host, port = parsed.hostname, parsed.port or 80
        ip = socket.gethostbyname(host)

        sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        sock.settimeout(timeout)

        transaction_id = random.randint(0, 2 ** 32 - 1)
        sock.sendto(struct.pack('!QII', 0x41727101980, 0, transaction_id), (ip, port))

        try:
            response, _ = sock.recvfrom(16)
            if len(response) >= 16:
                action, trans = struct.unpack('!II', response[:8])
                if trans == transaction_id and action == 0:
                    return 'alive', 'valid UDP tracker response'
            return 'alive', 'responded (partial)'
        except socket.timeout:
            return 'dead', 'no response'
    except socket.gaierror:
        return 'invalid', 'DNS resolution failed'
    except Exception as e:
        return 'dead', f'error: {str(e)[:50]}'
    finally:
        if sock is not None:
            try:
                sock.close()
            except Exception:
                pass


def validate_tracker(tracker_url, timeout=10):
    """Return (status, reason, protocol)."""
    try:
        parsed = urlparse(tracker_url)
        proto = parsed.scheme.lower()
        if not proto:
            return 'invalid', 'missing protocol', 'unknown'
        if not parsed.hostname:
            return 'invalid', 'invalid URL format', proto
        if proto in ('http', 'https'):
            return (*check_http_tracker(tracker_url, timeout), proto)
        if proto == 'udp':
            return (*check_udp_tracker(tracker_url, timeout), proto)
        return 'invalid', f'unsupported protocol: {proto}', proto
    except Exception as e:
        return 'invalid', f'parse error: {str(e)[:50]}', 'unknown'


def validate_timed(url, timeout=10, measure=True):
    started = time.perf_counter() if measure else None
    status, reason, protocol = validate_tracker(url, timeout)
    # Includes DNS and protocol negotiation; this is not an ICMP ping.
    latency = (time.perf_counter() - started) * 1000 if started is not None else None
    return status, reason, protocol, latency


# ============================================================================
# RESULT FILES (atomic writes, used by autosave and final save)
# ============================================================================

def write_results_file(path, results, total, partial=False, elapsed=None, include_latency=False):
    """Atomically write a categorized report. `results` = {status: [dict]}."""
    folder = os.path.dirname(os.path.abspath(path))
    os.makedirs(folder, exist_ok=True)
    tmp = path + ".tmp"
    done = sum(len(v) for v in results.values())

    with open(tmp, 'w', encoding='utf-8') as out:
        out.write("=" * 70 + "\n")
        out.write(f"{APP_NAME} RESULTS" + (" - PARTIAL (in progress / stopped)" if partial else "") + "\n")
        out.write(f"Generated: {datetime.now():%Y-%m-%d %H:%M:%S}\n")
        out.write("=" * 70 + "\n")
        out.write(f"Checked : {done} / {total}\n")
        out.write(f"Alive   : {len(results['alive'])}\n")
        out.write(f"Dead    : {len(results['dead'])}\n")
        out.write(f"Invalid : {len(results['invalid'])}\n")
        if elapsed is not None:
            out.write(f"Elapsed : {elapsed:.1f}s\n")
        out.write("=" * 70 + "\n")

        for status in ('alive', 'dead', 'invalid'):
            items = results[status]
            if not items:
                continue
            by_proto = {}
            for item in items:
                by_proto.setdefault(item['protocol'], []).append(item)

            out.write(f"\n{'#' * 70}\n# {status.upper()} TRACKERS ({len(items)})\n{'#' * 70}\n\n")
            for proto in sorted(by_proto):
                group = by_proto[proto]
                out.write(f"--- {proto.upper()} ({len(group)}) ---\n")
                for item in group:
                    line = item['url']
                    if include_latency:
                        ms = item.get('latency_ms')
                        line += f'  [response: {ms:.0f} ms]' if ms is not None else '  [response: not measured]'
                    out.write(line + '\n')
                    if status != 'alive':
                        out.write(f"  \u2514\u2500 Reason: {item['reason']}\n")
                out.write("\n")
        out.flush()
        os.fsync(out.fileno())
    os.replace(tmp, path)


def write_alive_list(path, results, include_latency=False):
    tmp = path + ".tmp"
    with open(tmp, 'w', encoding='utf-8') as out:
        for item in results['alive']:
            line = item['url']
            if include_latency:
                ms = item.get('latency_ms')
                line += f'\t{ms:.0f} ms' if ms is not None else '\tnot measured'
            out.write(line + '\n')
    os.replace(tmp, path)


def partial_path(output_path):
    root, ext = os.path.splitext(output_path)
    return f"{root}.partial{ext or '.txt'}"


