def run_gui():
    import tkinter as tk
    from tkinter import ttk, filedialog, messagebox

    # ---- palette -----------------------------------------------------------
    BG = '#100c1c'
    SURFACE = '#19132b'
    SURFACE2 = '#231b3b'
    BORDER = '#352a57'
    TEXT = '#efeaff'
    MUTED = '#9d90c4'
    PURPLE = '#8b5cf6'
    G1, G2, G3 = '#3b1d8f', '#7c3aed', '#c026d3'      # gradient stops
    OK, BAD, WARN = '#4ade80', '#f87171', '#fbbf24'
    FONT = 'Segoe UI'

    def hex2rgb(h):
        h = h.lstrip('#')
        return tuple(int(h[i:i + 2], 16) for i in (0, 2, 4))

    def lerp_color(stops, t):
        t = max(0.0, min(1.0, t))
        seg = t * (len(stops) - 1)
        i = min(int(seg), len(stops) - 2)
        f = seg - i
        a, b = hex2rgb(stops[i]), hex2rgb(stops[i + 1])
        return '#%02x%02x%02x' % tuple(int(a[k] + (b[k] - a[k]) * f) for k in range(3))

    def draw_gradient(canvas, w, h, stops, step=3, tag='grad'):
        canvas.delete(tag)
        for x in range(0, max(w, 1), step):
            canvas.create_rectangle(x, 0, x + step, h, width=0,
                                    fill=lerp_color(stops, x / max(w - 1, 1)), tags=tag)
        canvas.tag_lower(tag)

    class GradientButton(tk.Canvas):
        def __init__(self, parent, text, command, width=110, height=28,
                     stops=(G1, G2, G3), bg=SURFACE, **kw):
            super().__init__(parent, width=width, height=height, bg=bg,
                             highlightthickness=0, bd=0, cursor='hand2', **kw)
            self.text, self.command, self.w, self.h = text, command, width, height
            self.stops, self.enabled, self.hover = stops, True, False
            self.bind('<Enter>', lambda e: self._set_hover(True))
            self.bind('<Leave>', lambda e: self._set_hover(False))
            self.bind('<Button-1>', self._click)
            self.render()

        def _set_hover(self, value):
            self.hover = value
            self.render()

        def _click(self, _):
            if self.enabled and self.command:
                self.command()

        def set_state(self, enabled):
            self.enabled = enabled
            self.configure(cursor='hand2' if enabled else 'arrow')
            self.render()

        def set_text(self, text):
            self.text = text
            self.render()

        def render(self):
            self.delete('all')
            if self.enabled:
                stops = [lerp_color(self.stops, 0.15 if self.hover else 0),
                         lerp_color(self.stops, 0.65 if self.hover else 0.5),
                         lerp_color(self.stops, 1)]
                fg = '#ffffff'
            else:
                stops, fg = ['#2a2340', '#2a2340'], '#6f6590'
            for x in range(0, self.w, 2):
                self.create_rectangle(x, 0, x + 2, self.h, width=0,
                                      fill=lerp_color(stops, x / max(self.w - 1, 1)))
            self.create_text(self.w // 2, self.h // 2, text=self.text, fill=fg,
                             font=(FONT, 9, 'bold'))

    class FlatButton(tk.Label):
        def __init__(self, parent, text, command, **kw):
            super().__init__(parent, text=text, bg=SURFACE2, fg=TEXT, font=(FONT, 9),
                             padx=9, pady=3, cursor='hand2', **kw)
            self.command, self.active = command, False
            self.bind('<Button-1>', lambda e: self.command())
            self.bind('<Enter>', lambda e: self.configure(bg=BORDER))
            self.bind('<Leave>', lambda e: self._paint())

        def set_active(self, value):
            self.active = value
            self._paint()

        def _paint(self):
            self.configure(bg=PURPLE if self.active else SURFACE2,
                           fg='#ffffff' if self.active else TEXT)

    class GradientProgress(tk.Canvas):
        def __init__(self, parent, height=6, **kw):
            super().__init__(parent, height=height, bg=SURFACE2, highlightthickness=0, bd=0, **kw)
            self.fraction = 0.0
            self.bind('<Configure>', lambda e: self.render())

        def set(self, fraction):
            self.fraction = max(0.0, min(1.0, fraction))
            self.render()

        def render(self):
            self.delete('all')
            w, h = self.winfo_width(), self.winfo_height()
            fill_w = int(w * self.fraction)
            for x in range(0, fill_w, 3):
                self.create_rectangle(x, 0, x + 3, h, width=0,
                                      fill=lerp_color((G2, G3, '#f472b6'), x / max(w - 1, 1)))

    # ---- config -------------------------------------------------------------
    DEFAULTS = {
        'input': 'trackers.txt', 'output': 'filtered.txt',
        'threads': 30, 'timeout': 8,
        'autosave': True, 'mode': 'Both', 'every_n': 50, 'every_s': 30,
        'measure_latency': True, 'export_latency': False,
    }

    def load_config():
        cfg = dict(DEFAULTS)
        try:
            with open(CONFIG_PATH, 'r', encoding='utf-8') as fh:
                cfg.update(json.load(fh))
        except Exception:
            pass
        return cfg

    def save_config(cfg):
        try:
            with open(CONFIG_PATH, 'w', encoding='utf-8') as fh:
                json.dump(cfg, fh, indent=2)
        except Exception:
            pass

    # ---- application --------------------------------------------------------
    class App:
        MODES = ['Every N trackers', 'Every N seconds', 'Both']

        def __init__(self, root):
            self.root = root
            self.cfg = load_config()
            self.donor_receipt, self.receipt_error = load_donor_receipt()
