            self.donation_window = None
            self.donation_request_id = 0
            self.donation_busy = False
            self.donation_attempt = 0
            root.title(f"{APP_NAME} {APP_VERSION}")
            root.geometry("1160x660")
            root.minsize(1080, 540)
            root.configure(bg=BG)

            self.q = queue.Queue()
            self.results = {'alive': [], 'dead': [], 'invalid': []}
            self.rows = []                      # (status, protocol, url, reason)
            self.total = 0
            self.done = 0
            self.running = False
            self.cancel = threading.Event()
            self.start_time = 0.0
            self.last_save_time = 0.0
            self.last_save_count = 0
            self.run_id = 0
            self.shown = 0
            self.filter = tk.StringVar(value='all')
            self.search = tk.StringVar()
            self.icon_images = []
            self.icon_data = None
            self.icon_source_pixels = 0
            self.icon_generation = 0
            self.native_icon_state = None
            self.native_icon_stamp = None
            self.icon_refresh_job = None
            self.window_icon_photos = []
            self.tk_fallback_photos = []
            self.exit_visit = False
            self.closing = False

            self.v_in = tk.StringVar(value=self.cfg['input'])
